import * as THREE from 'three/webgpu';
import { color, uniform, mix, dot, normalWorld, cameraPosition, positionWorld, pow, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-badge';
  group.position.set(2.5, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const accent = color(0xff2a38);
  const ink = color(0x16161d);

  const rimStrength = uniform(1.2);
  const viewDir = cameraPosition.sub(positionWorld).normalize();
  const fresnel = pow(float(1.0).sub(dot(normalWorld, viewDir).clamp(0, 1)), 2.5).mul(rimStrength);
  const emissiveNode = mix(ink.mul(0.05), accent, fresnel);

  let mesh = null;
  const disposables = [];

  const gltf = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');

  function applyMaterials(root) {
    root.traverse((child) => {
      if (child.isMesh) {
        const mat = new THREE.MeshPhysicalMaterial({
          color: 0xe8ecf2,
          metalness: 0.5,
          roughness: 0.55,
          clearcoat: 0.2,
          clearcoatRoughness: 0.3,
          anisotropy: 0.6,
        });
        mat.emissiveNode = emissiveNode;
        mat.emissive = new THREE.Color(0xff2a38);
        mat.emissiveIntensity = 1.0;
        child.material = mat;
        child.castShadow = true;
        child.receiveShadow = true;
        disposables.push(mat);
      }
    });
  }

  if (gltf && gltf.scene) {
    mesh = gltf.scene.clone(true);
    applyMaterials(mesh);
    group.add(mesh);
  } else if (gltf && gltf.then) {
    // shouldn't happen since ctx.glbLoader is cached/sync per spec, but guard anyway
  }

  // Cinematic primitives
  ctx.primitives['parallax-scroll'](group, { intensity: 0.4, trigger: 'scroll' });
  ctx.primitives['magnetic-cursor'](group, { radius: 1.2, strength: 0.35, trigger: 'hover' });

  // Interaction state
  const baseY = group.position.y;
  let hoverTl = null;

  function onHoverStart() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    hoverTl.to(rimStrength, { value: 2.0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverEnd() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    hoverTl.to(rimStrength, { value: 1.2, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onClick() {
    if (group.userData.emit) {
      group.userData.emit('hub-journal.select');
    }
    gsap.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
  }

  // Weighted-settle entrance
  group.scale.set(0.001, 0.001, 0.001);
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1.04, y: 1.04, z: 1.04,
    duration: 0.6,
    ease: 'power4.out',
  }).to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.3,
    ease: 'power4.out',
  });

  group.userData.handlers = {
    hover: onHoverStart,
    hoverStart: onHoverStart,
    hoverEnd: onHoverEnd,
    click: onClick,
  };

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    settleTl.kill();
    disposables.forEach((mat) => mat.dispose && mat.dispose());
    group.traverse((child) => {
      if (child.isMesh && child.geometry) {
        child.geometry.dispose();
      }
    });
  };

  return group;
}
